//! Development-only oracle for the independent C formula executor.
//! This example is never linked into Mandelbulb3Dx.
use mb3d::{custom::{self,build_machine,code_addr,CustomFormula},formulas::Formula,iteration::Iteration,m3f::M3f};use std::sync::Arc;
fn main(){let scenario=std::env::var("CF_SCENARIO").unwrap_or_default().parse::<i32>().unwrap_or(0);let names="SurfBox";for line in names.lines(){let name=line.split('\t').next().unwrap();let p=std::path::Path::new("rust-assets/M3Formulas").join(format!("{name}.m3f"));let xyz=if scenario==1{[-0.713,0.827,-1.131]}else{match scenario{3=>[0.0,0.0,0.0],4=>[2.31,-1.72,0.93],5=>[0.000001,-0.000002,0.000003],_=>[0.371,0.213,0.419]}};let j=[0.137,-0.283,0.317,0.173];let mut v=[xyz[0],xyz[1],xyz[2],if scenario==1{-0.317}else{0.193}];let mut dr=1.0;let mut dist=0.0;let mut trap=0.0;
if p.exists(){let def=Arc::new(M3f::load(&p).unwrap());let mut c=CustomFormula::new(def.clone());if scenario==2&&!c.values.is_empty(){c.values[0]+=if def.options[0].ty==2{1.0}else{0.125};}let buf=def.var_buffer(&c.values,&custom::int_pow_addr);let hex=buf.iter().map(|b|format!("{b:02x}")).collect::<String>();println!("BUF\t{name}\t{hex}");
if let Some(prog)=&def.jit {let mut it=Iteration::default();it.v=v;it.j=j;prog.run(&mut it,&def,&c.values);v=it.v;}else{let mut m=build_machine(&[Some(&c)]);let b=custom::IT_BASE;for k in 0..3 {m.put_f64(b+24+8*k as u32,xyz[k]);m.put_f64(b+56+8*k as u32,xyz[k]);m.put_f64(b+80+8*k as u32,j[k]);}m.put_f64(b,j[3]);m.put_f64(b+48,if def.de_option==2||def.de_option==11{1.0}else{v[3]});m.put_f64(b+8,0.5*2.1345/64.0);m.put_f64(b+16,0.5*2.1345/64.0);m.put_f64(b+112,if def.de_option<20{xyz.iter().map(|a|a*a).sum::<f64>()+if [4,5,6].contains(&def.de_option){v[3]*v[3]}else{0.0}}else{0.0});m.put_f64(b+256,1.0);m.put_f64(b+288,1.0);m.put_u32(b+124,20);m.put_u32(b+128,256f32.to_bits());m.put_u32(b+104,custom::pconst_addr(0));m.put_u32(b+216,def.de_option as u32);m.put_u32(b+132,1);for i in 0..8{m.put_u32(b+156+4*i,custom::pconst_addr(i as usize));}for i in 0..6{let pow=if i==0{if def.si_pow>1.0{def.si_pow}else{c.values.first().copied().unwrap_or(0.0).abs()}}else{2.0};m.put_u32(b+220+4*i,(1.0f32/(pow.max(2.0).ln() as f32)).to_bits());}m.put_u32(b+212,((256f64.ln().ln())as f32).to_bits());for i in 0..4{m.put_u32(b+312+4*(i*4+i),1f32.to_bits());}
let r=if def.de_option>=20{m.call_difs(code_addr(0),b+144,custom::pconst_addr(0),0,1,custom::STACK_TOP,custom::MAX_STEPS)}else{m.call_formula(code_addr(0),b+56,custom::STACK_TOP,custom::MAX_STEPS)};if let Err(e)=r{eprintln!("ERROR {name}: {e}");continue;}for k in 0..3{v[k]=m.get_f64(b+24+8*k as u32);}if [4,5,6].contains(&def.de_option){v[3]=m.get_f64(b+48);}if def.de_option==2||def.de_option==11{dr=m.get_f64(b+48).abs();}if def.de_option==5||def.de_option==6{dr=m.get_f64(b+288).abs();}if def.de_option>=20{dr=m.get_f64(b+256);dist=m.get_f64(b+112);trap=m.get_f64(b+272);}}
}else{let mut f=Formula::default_for(name).unwrap();if scenario==2{let p=f.options()[0].clone();f.set_option(&p.0,p.1+0.125).unwrap();}let mut jj=j;f.iterate(&mut v,&mut jj,xyz.iter().map(|x|x*x).sum(),false);}
println!("VAL\t{name}\t{:.17}\t{:.17}\t{:.17}\t{:.17}\t{:.17}\t{:.17}\t{:.17}",v[0],v[1],v[2],v[3],dr,dist,trap);}}
